¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â Users (role 'fleet' or missing)
// =============================================================
class _UsersTab extends StatefulWidget {
  const _UsersTab();

  @override
  State<_UsersTab> createState() => _UsersTabState();
}

class _UsersTabState extends State<_UsersTab> {
  bool _loading = true;
  String _search = '';
  List<QueryDocumentSnapshot<Map<String, dynamic>>> _users = [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    if (!mounted) return;
    setState(() => _loading = true);
    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .get();
      final filtered = snap.docs.where((d) {
        final role = (d.data()['role'] ?? 'fleet').toString();
        return role == 'fleet' || role.isEmpty;
      }).toList();
      if (!mounted) return;
      setState(() {
        _users = filtered;
        _loading = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _loading = false);
    }
  }

  List<QueryDocumentSnapshot<Map<String, dynamic>>> get _filtered {
    final q = _search.trim().toLowerCase();
    if (q.isEmpty) return _users;
    final wantsSuspended = q.startsWith('susp');
    final wantsActive = q.startsWith('act') && !wantsSuspended;
    return _users.where((d) {
      final m = d.data();
      final name = (m['name'] ?? '').toString().toLowerCase();
      final email = (m['email'] ?? '').toString().toLowerCase();
      final phone = (m['phone'] ?? '').toString().toLowerCase();
      final isSuspended = m['suspended'] == true;
      if (wantsSuspended) return isSuspended;
      if (wantsActive) return !isSuspended;
      return name.contains(q) || email.contains(q) || phone.contains(q);
    }).toList();
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFF00C853)));
    }
    if (_users.isEmpty) {
      return RefreshIndicator(
        color: const Color(0xFF00C853),
        onRefresh: _load,
        child: _emptyState(
          icon: Icons.people_outline,
          title: 'No Users',
          subtitle: 'Normal users will appear here.',
        ),
      );
    }
    final filtered = _filtered;
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
          child: TextField(
            onChanged: (v) => setState(() => _search = v),
            style: const TextStyle(color: Colors.white),
            decoration: InputDecoration(
              hintText: 'Search by name, email or phone',
              hintStyle: const TextStyle(color: Color(0xFF4A5568)),
              prefixIcon: const Icon(Icons.search, color: Color(0xFF8892B0)),
              filled: true,
              fillColor: const Color(0xFF111827),
              contentPadding: const EdgeInsets.symmetric(vertical: 0),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(14),
                borderSide: const BorderSide(color: Color(0xFF1F2937)),
              ),
              enabledBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(14),
                borderSide: const BorderSide(color: Color(0xFF1F2937)),
              ),
              focusedBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(14),
                borderSide: const BorderSide(color: Color(0x6600C853)),
              ),
            ),
          ),
        ),
        Expanded(
          child: RefreshIndicator(
            color: const Color(0xFF00C853),
            onRefresh: _load,
            child: filtered.isEmpty
                ? ListView(
                    physics: const AlwaysScrollableScrollPhysics(),
                    children: const [
                      SizedBox(height: 120),
                      Icon(Icons.search_off,
                          color: Color(0xFF4A5568), size: 48),
                      SizedBox(height: 16),
                      Text('No users match your search',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                              color: Color(0xFF8892B0), fontSize: 14)),
                    ],
                  )
                : ListView.separated(
                    padding: const EdgeInsets.all(16),
                    itemCount: filtered.length,
                    separatorBuilder: (_, __) =>
                        const SizedBox(height: 10),
                    itemBuilder: (context, i) {
                      final doc = filtered[i];
                      final u = doc.data();
                      final suspended = u['suspended'] == true;
                      return _userCard(
                        name: (u['name'] ?? 'Unnamed').toString(),
                        email: (u['email'] ?? '').toString(),
                        phone: (u['phone'] ?? '').toString(),
                        role: 'fleet',
                        suspended: suspended,
                        onTap: () => _showUserManageSheet(doc),
                      );
                    },
                  ),
          ),
        ),
      ],
    );
  }

  Future<void> _showUserManageSheet(
      QueryDocumentSnapshot<Map<String, dynamic>> doc) async {
    final m = doc.data();
    final name = (m['name'] ?? 'User').toString();
    final suspended = m['suspended'] == true;
    final action = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: const Color(0xFF111827),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (ctx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Padding(
              padding: const EdgeInsets.all(16),
              child: Text(name,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.w700)),
            ),
            ListTile(
              leading: Icon(
                  suspended ? Icons.play_circle : Icons.pause_circle,
                  color: suspended
                      ? const Color(0xFF00C853)
                      : const Color(0xFFFFA000)),
              title: Text(
                  suspended ? 'Unsuspend Account' : 'Suspend Account',
                  style: const TextStyle(color: Colors.white)),
              onTap: () => Navigator.pop(
                  ctx, suspended ? 'unsuspend' : 'suspend'),
            ),
            const Divider(color: Color(0xFF1F2937), height: 1),
            ListTile(
              leading: const Icon(Icons.delete_outline,
                  color: Color(0xFFD32F2F)),
              title: const Text('Delete User',
                  style: TextStyle(
                      color: Color(0xFFD32F2F),
                      fontWeight: FontWeight.w700)),
              onTap: () => Navigator.pop(ctx, 'delete'),
            ),
            const SizedBox(height: 12),
          ],
        ),
      ),
    );

    if (action == null) return;
    try {
      if (action == 'suspend') {
        await doc.reference.update({'suspended': true});
        _snack('Suspended ' + name);
      } else if (action == 'unsuspend') {
        await doc.reference.update({'suspended': false});
        _snack('Unsuspended ' + name);
      } else if (action == 'delete') {
        final ok = await _confirm('Delete User',
            'Do you want to delete ' + name +
                '? This cannot be undone.');
        if (ok != true) return;
        await doc.reference.delete();
        _snack('Deleted ' + name);
      }
      _load();
    } catch (e) {
      _snack('Action failed: ' + e.toString());
    }
  }

  void _snack(String s) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(s)));
  }

  Future<bool?> _confirm(String title, String body) {
    return showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF111827),
        title: Text(title, style: const TextStyle(color: Colors.white)),
        content: Text(body,
            style: const TextStyle(color: Color(0xFFB8C7DA))),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Cancel',
                style: TextStyle(color: Color(0xFF8892B0))),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Confirm',
                style: TextStyle(color: Color(0xFFD32F2F))),
          ),
        ],
      ),
    );
  }
}

class _StaffTab extends StatefulWidget {
  const _StaffTab();

  @override
  State<_StaffTab> createState() => _StaffTabState();
}

class _StaffTabState extends State<_StaffTab> {
  bool _loading = true;
  String _search = '';
  List<QueryDocumentSnapshot<Map<String, dynamic>>> _staff = [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    if (!mounted) return;
    setState(() => _loading = true);
    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .get();
      final filtered = snap.docs.where((d) {
        final role = (d.data()['role'] ?? '').toString();
        return role == 'operator' || role == 'technician';
      }).toList();
      if (!mounted) return;
      setState(() {
        _staff = filtered;
        _loading = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _loading = false);
    }
  }

  List<QueryDocumentSnapshot<Map<String, dynamic>>> get _filtered {
    final q = _search.trim().toLowerCase();
    if (q.isEmpty) return _staff;
    final wantsSuspended = q.startsWith('susp');
    final wantsActive = q.startsWith('act') && !wantsSuspended;
    return _staff.where((d) {
      final m = d.data();
      final name = (m['name'] ?? '').toString().toLowerCase();
      final email = (m['email'] ?? '').toString().toLowerCase();
      final phone = (m['phone'] ?? '').toString().toLowerCase();
      final isSuspended = m['suspended'] == true;
      if (wantsSuspended) return isSuspended;
      if (wantsActive) return !isSuspended;
      return name.contains(q) || email.contains(q) || phone.contains(q);
    }).toList();
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFF00C853)));
    }
    if (_staff.isEmpty) {
      return RefreshIndicator(
        color: const Color(0xFF00C853),
        onRefresh: _load,
        child: _emptyState(
          icon: Icons.badge_outlined,
          title: 'No Staff Yet',
          subtitle: 'Approved operators and technicians will appear here.',
        ),
      );
    }
    final filtered = _filtered;
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
          child: TextField(
            onChanged: (v) => setState(() => _search = v),
            style: const TextStyle(color: Colors.white),
            decoration: InputDecoration(
              hintText: 'Search by name, email or phone',
              hintStyle: const TextStyle(color: Color(0xFF4A5568)),
              prefixIcon: const Icon(Icons.search, color: Color(0xFF8892B0)),
              filled: true,
              fillColor: const Color(0xFF111827),
              contentPadding: const EdgeInsets.symmetric(vertical: 0),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(14),
                borderSide: const BorderSide(color: Color(0xFF1F2937)),
              ),
              enabledBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(14),
                borderSide: const BorderSide(color: Color(0xFF1F2937)),
              ),
              focusedBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(14),
                borderSide: const BorderSide(color: Color(0x6600C853)),
              ),
            ),
          ),
        ),
        Expanded(
          child: RefreshIndicator(
            color: const Color(0xFF00C853),
            onRefresh: _load,
            child: filtered.isEmpty
                ? ListView(
                    physics: const AlwaysScrollableScrollPhysics(),
                    children: const [
                      SizedBox(height: 120),
                      Icon(Icons.search_off,
                          color: Color(0xFF4A5568), size: 48),
                      SizedBox(height: 16),
                      Text('No staff match your search',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                              color: Color(0xFF8892B0), fontSize: 14)),
                    ],
                  )
                : ListView.separated(
                    padding: const EdgeInsets.all(16),
                    itemCount: filtered.length,
                    separatorBuilder: (_, __) =>
                        const SizedBox(height: 10),
                    itemBuilder: (context, i) {
                      final doc = filtered[i];
                      final u = doc.data();
                      final role = (u['role'] ?? '').toString();
                      final suspended = u['suspended'] == true;
                      return _userCard(
                        name: (u['name'] ?? 'Unnamed').toString(),
                        email: (u['email'] ?? '').toString(),
                        phone: (u['phone'] ?? '').toString(),
                        role: role,
                        suspended: suspended,
                        onTap: () => _showStaffManageSheet(doc),
                      );
                    },
                  ),
          ),
        ),
      ],
    );
  }

  Future<void> _showStaffManageSheet(
      QueryDocumentSnapshot<Map<String, dynamic>> doc) async {
    final m = doc.data();
    final name = (m['name'] ?? 'Staff').toString();
    final suspended = m['suspended'] == true;
    final role = (m['role'] ?? '').toString();
    final action = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: const Color(0xFF111827),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (ctx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Padding(
              padding: const EdgeInsets.all(16),
              child: Text(name,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.w700)),
            ),
            ListTile(
              leading: Icon(
                  suspended ? Icons.play_circle : Icons.pause_circle,
                  color: suspended
                      ? const Color(0xFF00C853)
                      : const Color(0xFFFFA000)),
              title: Text(
                  suspended ? 'Unsuspend Account' : 'Suspend Account',
                  style: const TextStyle(color: Colors.white)),
              onTap: () => Navigator.pop(
                  ctx, suspended ? 'unsuspend' : 'suspend'),
            ),
            ListTile(
              leading: const Icon(Icons.person_remove_outlined,
                  color: Color(0xFFFFA000)),
              title: const Text('Demote to Normal User',
                  style: TextStyle(color: Colors.white)),
              onTap: () => Navigator.pop(ctx, 'demote'),
            ),
            const Divider(color: Color(0xFF1F2937), height: 1),
            ListTile(
              leading: const Icon(Icons.delete_outline,
                  color: Color(0xFFD32F2F)),
              title: const Text('Delete Account',
                  style: TextStyle(
                      color: Color(0xFFD32F2F),
                      fontWeight: FontWeight.w700)),
              onTap: () => Navigator.pop(ctx, 'delete'),
            ),
            const SizedBox(height: 12),
          ],
        ),
      ),
    );

    if (action == null) return;
    try {
      if (action == 'suspend') {
        await doc.reference.update({'suspended': true});
        if (role == 'operator') {
          await _offlineOperatorStations(doc.id);
        }
        _snack('Suspended ' + name);
      } else if (action == 'unsuspend') {
        await doc.reference.update({'suspended': false});
        _snack('Unsuspended ' + name);
      } else if (action == 'demote') {
        final ok = await _confirm('Demote to Normal User',
            'Do you want to demote ' + name + ' to a normal user?');
        if (ok != true) return;
        await doc.reference.update({'role': 'fleet'});
        _snack('Demoted ' + name);
      } else if (action == 'delete') {
        final ok = await _confirm('Delete Account',
            'Do you want to delete ' + name +
                '? This cannot be undone.');
        if (ok != true) return;
        await doc.reference.delete();
        _snack('Deleted ' + name);
      }
      _load();
    } catch (e) {
      _snack('Action failed: ' + e.toString());
    }
  }

  Future<void> _offlineOperatorStations(String operatorUid) async {
    final snap = await FirebaseFirestore.instance
        .collection('stations')
        .where('operatorId', isEqualTo: operatorUid)
        .get();
    if (snap.docs.isEmpty) return;
    final batch = FirebaseFirestore.instance.batch();
    for (final d in snap.docs) {
      batch.update(d.reference, {'status': 'Offline'});
    }
    await batch.commit();
  }

  void _snack(String s) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(s)));
  }

  Future<bool?> _confirm(String title, String body) {
    return showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF111827),
        title: Text(title, style: const TextStyle(color: Colors.white)),
        content: Text(body,
            style: const TextStyle(color: Color(0xFFB8C7DA))),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Cancel',
                style: TextStyle(color: Color(0xFF8892B0))),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Confirm',
                style: TextStyle(color: Color(0xFFD32F2F))),
          ),
        ],
      ),
    );
  }
}

Widget _userCard({
  required String name,
  required String email,
  required String phone,
  required String role,
  required bool suspended,
  required VoidCallback onTap,
}) {
  Color c;
  String label;
  switch (role) {
    case 'operator':
      c = const Color(0xFF00C853);
      label = 'OPERATOR';
      break;
    case 'technician':
      c = const Color(0xFF4FA3E8);
      label = 'TECHNICIAN';
      break;
    case 'admin':
      c = const Color(0xFFE91E63);
      label = 'ADMIN';
      break;
    default:
      c = const Color(0xFF8892B0);
      label = 'USER';
  }

  final statusColor =
      suspended ? const Color(0xFFD32F2F) : const Color(0xFF00C853);
  final statusLabel = suspended ? 'SUSPENDED' : 'ACTIVE';

  return Material(
    color: Colors.transparent,
    child: InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(14),
      child: Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: const Color(0xFF111827),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: const Color(0xFF1F2937)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text(name,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 15,
                          fontWeight: FontWeight.w700)),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                    color: c.withOpacity(0.15),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(color: c.withOpacity(0.5)),
                  ),
                  child: Text(label,
                      style: TextStyle(
                          color: c,
                          fontSize: 10,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 1)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Container(
              padding: const EdgeInsets.symmetric(
                  horizontal: 8, vertical: 2),
              decoration: BoxDecoration(
                color: statusColor.withOpacity(0.15),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: statusColor.withOpacity(0.5)),
              ),
              child: Text(statusLabel,
                  style: TextStyle(
                      color: statusColor,
                      fontSize: 9,
                      fontWeight: FontWeight.w800,
                      letterSpacing: 1)),
            ),
            const SizedBox(height: 8),
            if (email.isNotEmpty)
              Text(email,
                  style: const TextStyle(
                      color: Color(0xFF8892B0), fontSize: 12)),
            if (phone.isNotEmpty)
              Text(phone,
                  style: const TextStyle(
                      color: Color(0xFF8892B0), fontSize: 12)),
          ],
        ),
      ),
    ),
  );
}